import json
import os
import urllib.request
import urllib.error


class LocalStorage:
    def __init__(self, filepath: str = 'storage.json'):
        self.filepath = filepath
        self._data: dict = {}
        self._load()

    def _load(self):
        if os.path.exists(self.filepath):
            with open(self.filepath, 'r') as f:
                self._data = json.load(f)

    def _save(self):
        with open(self.filepath, 'w') as f:
            json.dump(self._data, f)

    def get_item(self, key: str, default=None):
        return self._data.get(key, default)

    def set_item(self, key: str, value) -> None:
        self._data[key] = value
        self._save()

    def remove_item(self, key: str) -> None:
        if key in self._data:
            del self._data[key]
            self._save()


class FetchResult:
    def __init__(self):
        self.data = None
        self.loading = True
        self.error = None

    def __repr__(self):
        return f'FetchResult(data={self.data}, loading={self.loading}, error={self.error})'


def fetch_data(url: str) -> FetchResult:
    result = FetchResult()
    try:
        req = urllib.request.Request(url)
        with urllib.request.urlopen(req) as response:
            data = json.loads(response.read().decode())
            result.data = data
            result.loading = False
    except urllib.error.HTTPError as e:
        result.error = f'HTTP {e.code}: {e.reason}'
        result.loading = False
    except Exception as e:
        result.error = str(e)
        result.loading = False
    return result

